internal object AssistantsListRunsOperation {
    /**
     * Lists runs belonging to a thread. Use `order` to sort runs by creation time and `after` or
     * `before` to navigate through the results. The returned run statuses show whether each run is
     * queued, active, completed, or in another state.
     *
     * Returns a list of runs belonging to a thread.
     *
     * @param threadId The ID of the thread the run belongs to.
     * @param limit A limit on the number of objects to be returned. Limit can range between 1 and
     *   100, and the default is 20.
     * @param order Sort order by the `created_at` timestamp of the objects. `asc` for ascending
     *   order and `desc` for descending order.
     * @param after A cursor for use in pagination. `after` is an object ID that defines your place
     *   in the list. For instance, if you make a list request and receive 100 objects, ending with
     *   obj_foo, your subsequent call can include after=obj_foo in order to fetch the next page of
     *   the list.
     * @param before A cursor for use in pagination. `before` is an object ID that defines your
     *   place in the list. For instance, if you make a list request and receive 100 objects,
     *   starting with obj_foo, your subsequent call can include before=obj_foo in order to fetch
     *   the previous page of the list.
     */
    fun listRuns(
        clientConfig: ClientConfig,
        threadId: String,
        limit: Long? = null,
        order: ListRunsParameterEnum? = null,
        after: String? = null,
        before: String? = null,
        options: RequestOptions? = null,
    ): ListRunsResponse {
        return SdkClient.request<ListRunsResponse>(
                SdkClient.RequestSpec(
                    "GET",
                    "/threads/${SdkClient.encodePathSegment(threadId)}/runs",
                    config = clientConfig,
                    query =
                        mapOf(
                            "limit" to SdkClient.queryValue(limit, "form", true),
                            "order" to SdkClient.queryValue(order, "form", true),
                            "after" to SdkClient.queryValue(after, "form", true),
                            "before" to SdkClient.queryValue(before, "form", true),
                        ),
                    operationId = "listRuns",
                    decoder = SdkClient.ResponseDecoder.JSON,
                    options = options,
                    errors = mapOf("429" to ErrorResponse::class.java),
                )
            )
            .data
    }

    /**
     * Lists runs belonging to a thread. Use `order` to sort runs by creation time and `after` or
     * `before` to navigate through the results. The returned run statuses show whether each run is
     * queued, active, completed, or in another state.
     *
     * Returns a list of runs belonging to a thread.
     *
     * @param threadId The ID of the thread the run belongs to.
     * @param limit A limit on the number of objects to be returned. Limit can range between 1 and
     *   100, and the default is 20.
     * @param order Sort order by the `created_at` timestamp of the objects. `asc` for ascending
     *   order and `desc` for descending order.
     * @param after A cursor for use in pagination. `after` is an object ID that defines your place
     *   in the list. For instance, if you make a list request and receive 100 objects, ending with
     *   obj_foo, your subsequent call can include after=obj_foo in order to fetch the next page of
     *   the list.
     * @param before A cursor for use in pagination. `before` is an object ID that defines your
     *   place in the list. For instance, if you make a list request and receive 100 objects,
     *   starting with obj_foo, your subsequent call can include before=obj_foo in order to fetch
     *   the previous page of the list.
     */
    fun listRunsPaginated(
        clientConfig: ClientConfig,
        threadId: String,
        limit: Long? = null,
        order: ListRunsParameterEnum? = null,
        after: String? = null,
        before: String? = null,
        options: RequestOptions? = null,
        yieldFn: (RunObject) -> Boolean,
    ) {
        var cursor = after
        while (true) {
            val page = listRuns(clientConfig, threadId, limit, order, cursor, before, options)
            val items = page.`data`.orEmpty()
            if (items.isEmpty()) return
            for (item in items) {
                if (!yieldFn(item)) return
            }
            if (page.hasMore != true) return
            val nextCursor = page.lastId
            cursor = nextCursor
        }
    }

    fun listRunsPages(
        clientConfig: ClientConfig,
        threadId: String,
        limit: Long? = null,
        order: ListRunsParameterEnum? = null,
        after: String? = null,
        before: String? = null,
        options: RequestOptions? = null,
        yieldPage: (Assistants.ListRunsPage) -> Boolean,
    ) {
        var cursor = after
        while (true) {
            val page = listRuns(clientConfig, threadId, limit, order, cursor, before, options)
            val items = page.`data`.orEmpty()
            if (items.isEmpty()) return
            val nextCursor = page.lastId
            val hasMore = page.hasMore == true
            if (!yieldPage(Assistants.ListRunsPage(page, items, hasMore))) return
            if (!hasMore) return
            cursor = nextCursor
        }
    }
}

internal object AssistantsCreateRunOperation {
    /**
     * Creates a run on a thread using the specified assistant. Supply `assistant_id` and optionally
     * override the assistant’s model, instructions, tools, or generation settings for this run. If
     * the run requires tool outputs, submit them with POST
     * /threads/{thread_id}/runs/{run_id}/submit_tool_outputs.
     *
     * Create a run.
     *
     * @param threadId The ID of the thread to run.
     * @param assistantId The ID of the assistant to use to execute this run.
     * @param include A list of additional fields to include in the response. Currently the only
     *   supported value is `step_details.tool_calls*].file_search.results[*].content` to fetch the
     *   file search result content. See the \[file search tool documentation for more information.
     * @param model The ID of the Model to be used to execute this run. If a value is provided here,
     *   it will override the model associated with the assistant. If not, the model associated with
     *   the assistant will be used.
     * @param reasoningEffort Optional API value serialized in the `reasoning_effort` wire field.
     * @param instructions Overrides the instructions of the assistant. This is useful for modifying
     *   the behavior on a per-run basis.
     * @param additionalInstructions Appends additional instructions at the end of the instructions
     *   for the run. This is useful for modifying the behavior on a per-run basis without
     *   overriding other instructions.
     * @param additionalMessages Adds additional messages to the thread before creating the run.
     * @param tools Override the tools the assistant can use for this run. This is useful for
     *   modifying the behavior on a per-run basis.
     * @param metadata Set of 16 key-value pairs that can be attached to an object. This can be
     *   useful for storing additional information about the object in a structured format, and
     *   querying for objects via API or the dashboard. Keys are strings with a maximum length of 64
     *   characters. Values are strings with a maximum length of 512 characters.
     * @param temperature What sampling temperature to use, between 0 and 2. Higher values like 0.8
     *   will make the output more random, while lower values like 0.2 will make it more focused and
     *   deterministic.
     * @param topP An alternative to sampling with temperature, called nucleus sampling, where the
     *   model considers the results of the tokens with top_p probability mass. So 0.1 means only
     *   the tokens comprising the top 10% probability mass are considered. We generally recommend
     *   altering this or temperature but not both.
     * @param stream If `true`, returns a stream of events that happen during the Run as server-sent
     *   events, terminating when the Run enters a terminal state with a `data: [DONE]` message.
     * @param maxPromptTokens The maximum number of prompt tokens that may be used over the course
     *   of the run. The run will make a best effort to use only the number of prompt tokens
     *   specified, across multiple turns of the run. If the run exceeds the number of prompt tokens
     *   specified, the run will end with status `incomplete`. See `incomplete_details` for more
     *   info.
     * @param maxCompletionTokens The maximum number of completion tokens that may be used over the
     *   course of the run. The run will make a best effort to use only the number of completion
     *   tokens specified, across multiple turns of the run. If the run exceeds the number of
     *   completion tokens specified, the run will end with status `incomplete`. See
     *   `incomplete_details` for more info.
     * @param truncationStrategy Optional API value serialized in the `truncation_strategy` wire
     *   field.
     * @param toolChoice Optional API value serialized in the `tool_choice` wire field.
     * @param parallelToolCalls Whether to enable parallel function calling during tool use.
     * @param responseFormat Specifies the format that the model must output. Compatible with
     *   GPT-4o, GPT-4 Turbo, and all GPT-3.5 Turbo models since `gpt-3.5-turbo-1106`. Setting to `{
     *   "type": "json_schema", "json_schema": {...} }` enables Structured Outputs which ensures the
     *   model will match your supplied JSON schema. Learn more in the Structured Outputs guide.
     *   Setting to `{ "type": "json_object" }` enables JSON mode, which ensures the message the
     *   model generates is valid JSON. **Important:** when…
