    fun createRun(
        clientConfig: ClientConfig,
        request: Assistants.CreateRunParams,
        options: RequestOptions? = null,
    ): RunObject {
        validateCreateRunRequest(request)

        return SdkClient.request<RunObject>(
                SdkClient.RequestSpec(
                    "POST",
                    "/threads/${SdkClient.encodePathSegment(request.threadId)}/runs",
                    config = clientConfig,
                    query =
                        mapOf("include[]" to SdkClient.queryValue(request.include, "form", true)),
                    body = buildCreateRunBody(request),
                    operationId = "createRun",
                    decoder = SdkClient.ResponseDecoder.JSON,
                    options = options,
                    errors = mapOf("429" to ErrorResponse::class.java),
                )
            )
            .data
    }

    private fun validateCreateRunRequest(request: Assistants.CreateRunParams) {
        val toolsValue = request.tools?.getOrNull()
        if (toolsValue != null) {
            Validation.validateItems("tools", toolsValue, Validation.LengthOpts(max = 20))
        }

        val temperatureValue = request.temperature?.getOrNull()
        if (temperatureValue != null) {
            Validation.validateRange(
                "temperature",
                temperatureValue,
                Validation.RangeOpts(min = 0.0, max = 2.0),
            )
        }

        val topPValue = request.topP?.getOrNull()
        if (topPValue != null) {
            Validation.validateRange("top_p", topPValue, Validation.RangeOpts(min = 0.0, max = 1.0))
        }

        val maxPromptTokensValue = request.maxPromptTokens?.getOrNull()
        if (maxPromptTokensValue != null) {
            Validation.validateRange(
                "max_prompt_tokens",
                maxPromptTokensValue,
                Validation.RangeOpts(min = 256.0),
            )
        }

        val maxCompletionTokensValue = request.maxCompletionTokens?.getOrNull()
        if (maxCompletionTokensValue != null) {
            Validation.validateRange(
                "max_completion_tokens",
                maxCompletionTokensValue,
                Validation.RangeOpts(min = 256.0),
            )
        }
    }

