        buildMap {
            putAll(buildCreateRunBodyPart1(request))
            putAll(buildCreateRunBodyPart2(request))
        }

    private fun buildCreateRunBodyPart1(request: Assistants.CreateRunParams): Map<String, Any?> =
        SdkClient.bodyMap(
            "assistant_id" to (request.assistantId),
            "model" to (request.model ?: SdkClient.SdkOptional.Omitted),
            "reasoning_effort" to (request.reasoningEffort ?: SdkClient.SdkOptional.Omitted),
            "instructions" to (request.instructions ?: SdkClient.SdkOptional.Omitted),
            "additional_instructions" to
                (request.additionalInstructions ?: SdkClient.SdkOptional.Omitted),
            "additional_messages" to (request.additionalMessages ?: SdkClient.SdkOptional.Omitted),
            "tools" to (request.tools ?: SdkClient.SdkOptional.Omitted),
            "metadata" to (request.metadata ?: SdkClient.SdkOptional.Omitted),
            "temperature" to (request.temperature ?: SdkClient.SdkOptional.Omitted),
            "top_p" to (request.topP ?: SdkClient.SdkOptional.Omitted),
            "stream" to (request.stream ?: SdkClient.SdkOptional.Omitted),
            "max_prompt_tokens" to (request.maxPromptTokens ?: SdkClient.SdkOptional.Omitted),
        )

    private fun buildCreateRunBodyPart2(request: Assistants.CreateRunParams): Map<String, Any?> =
        SdkClient.bodyMap(
            "max_completion_tokens" to
                (request.maxCompletionTokens ?: SdkClient.SdkOptional.Omitted),
            "truncation_strategy" to (SdkClient.omitIfNull(request.truncationStrategy)),
            "tool_choice" to (SdkClient.omitIfNull(request.toolChoice)),
            "parallel_tool_calls" to (SdkClient.omitIfNull(request.parallelToolCalls)),
            "response_format" to (request.responseFormat ?: SdkClient.SdkOptional.Omitted),
        )
}
